class Solution {
public:
    int binaryGap(int n) {
        int last = -1, best = 0;
        for (int pos = 0; n > 0; pos++, n >>= 1) {
            if (n & 1) {
                if (last >= 0) best = max(best, pos - last);
                last = pos;
            }
        }
        return best;
    }
};
